)?>">api/channel-webhook?token=<?=htmlspecialchars(substr($c['access_token'],0,10))?>…<?=htmlspecialchars(substr($c['access_token'],30,4))?>…</span><button type="button" class="ical-copy-btn" data-copy="https://nexustraveltech.com/api/channel-webhook?token=<?=htmlspecialchars($c['access_token'])?>">Kopyala</button></div><form method="post" style="margin:4px 0 2px"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="connection_token_reset"><input type="hidden" name="connection_id" value="<?=(int)$c['id']?>"><button type="submit" class="conn-token-reset-btn" onclick="return confirm('Token sıfırlanırsa bu kanalın webhook adresi DEĞİŞİR ve OTA tarafında güncellenmesi gerekir. Devam edilsin mi?');">↻ Tokenı sıfırla</button></form><?php $cSeen=$pdo->prepare("SELECT id, request_payload, created_at, property_id FROM channel_sync_logs WHERE channel_connection_id=? AND direction='pull' AND request_payload IS NOT NULL".$seenFilter." ORDER BY id DESC LIMIT ?");$cSeen->execute([(int)$c['id'],$seenWindow]);$cCodes=[];foreach($cSeen->fetchAll() as $sl){$dec=json_decode((string)$sl['request_payload'],true);if(!is_array($dec)||!isset($dec['entries'])||!is_array($dec['entries']))continue;foreach($dec['entries'] as $en){if(is_array($en)&&isset($en['external_room_id'])&&trim((string)$en['external_room_id'])!==''){$code=trim((string)$en['external_room_id']);if(!isset($cCodes[$code]))$cCodes[$code]=['c'=>0,'t'=>(string)$sl['created_at'],'p'=>(int)$sl['property_id'],'lid'=>(int)$sl['id']];$cCodes[$code]['c']++;}}}$cUnmatched=[];$cSuggested=[];$cSeenInfo=$cCodes;if($cCodes){$cMap=$pdo->prepare('SELECT m.external_room_id, m.room_type_id, m.status, m.suggestion_score, p.id property_id, rt.name room_name, p.name property_name FROM channel_room_mappings m LEFT JOIN room_types rt ON rt.id=m.room_type_id LEFT JOIN properties p ON p.id=m.property_id WHERE m.channel_connection_id=?');$cMap->execute([(int)$c['id']]);$cInfo=[];foreach($cMap->fetchAll() as $mc)$cInfo[$mc['external_room_id']]=$mc;foreach(array_keys($cCodes) as $code){if(!isset($cInfo[$code])){$cUnmatched[$code]=$cCodes[$code];continue;}if($cInfo[$code]['status']==='suggested')$cSuggested[$code]=$cInfo[$code];}}// Eşlenmemiş oda kodları için en iyi eşleşen oda tipi (bölüm 3 hızlı eşleştirme hedefi).
$cBestRoom=[];if($cUnmatched){$cPropIds=array_values(array_unique(array_filter(array_map(fn($v)=>(int)($v['p']??0),$cUnmatched),fn($i)=>$i>0)));if($cPropIds){$cRooms=$pdo->query("SELECT id, name, property_id FROM room_types WHERE property_id IN (".implode(',',$cPropIds).") AND status='active' ORDER BY name")->fetchAll();foreach($cUnmatched as $ucode=>$uv){$bestId=0;$bestSc=0;foreach($cRooms as $cr){if((int)$cr['property_id']!==(int)($uv['p']??0))continue;$sc=(int)round(name_similarity((string)$ucode,(string)$cr['name'])*100);if($sc>=30&&$sc>$bestSc){$bestSc=$sc;$bestId=(int)$cr['id'];}}if($bestId>0)$cBestRoom[$ucode]=$bestId;}}}
uasort($cUnmatched,function($a,$b){return (($b['c']??0)<=>($a['c']??0))?:strcmp((string)($b['t']??''),(string)($a['t']??''));});uasort($cSuggested,function($a,$b)use($cSeenInfo){$ai=$cSeenInfo[$a['external_room_id']]??['c'=>0,'t'=>''];$bi=$cSeenInfo[$b['external_room_id']]??['c'=>0,'t'=>''];return (($bi['c']??0)<=>($ai['c']??0))?:strcmp((string)($bi['t']??''),(string)($ai['t']??''));});
// Fiyat planı kodları — aynı pencerede görülen external_rate_plan_id kodları + channel_rate_plan_mappings durumu.
$cPlanCodes=[];foreach($cSeen->fetchAll() as $sl){$dec=json_decode((string)$sl['request_payload'],true);if(!is_array($dec)||!isset($dec['entries'])||!is_array($dec['entries']))continue;foreach($dec['entries'] as $en){if(is_array($en)&&isset($en['external_rate_plan_id'])&&trim((string)$en['external_rate_plan_id'])!==''){$code=trim((string)$en['external_rate_plan_id']);if(!isset($cPlanCodes[$code]))$cPlanCodes[$code]=['c'=>0,'t'=>(string)$sl['created_at'],'p'=>(int)$sl['property_id'],'lid'=>(int)$sl['id']];$cPlanCodes[$code]['c']++;}}}
$cPlanUnmatched=[];$cPlanSuggested=[];$cPlanSeenInfo=$cPlanCodes;$cPlanInfo=[];if($cPlanCodes){$cPlanMap=$pdo->prepare('SELECT pm.external_rate_plan_id, pm.rate_plan_id, pm.status, pm.suggestion_score, p.id property_id, rp.name plan_name, p.name property_name FROM channel_rate_plan_mappings pm LEFT JOIN rate_plans rp ON rp.id=pm.rate_plan_id LEFT JOIN properties p ON p.id=pm.property_id WHERE pm.channel_connection_id=?');$cPlanMap->execute([(int)$c['id']]);foreach($cPlanMap->fetchAll() as $pmc)$cPlanInfo[$pmc['external_rate_plan_id']]=$pmc;foreach(array_keys($cPlanCodes) as $code){if(!isset($cPlanInfo[$code])){$cPlanUnmatched[$code]=$cPlanCodes[$code];continue;}if($cPlanInfo[$code]['status']==='suggested')$cPlanSuggested[$code]=$cPlanInfo[$code];}}
$cPlanSort=function($a,$b)use($cPlanSeenInfo){$ai=$cPlanSeenInfo[$a['external_rate_plan_id']]??['c'=>0,'t'=>''];$bi=$cPlanSeenInfo[$b['external_rate_plan_id']]??['c'=>0,'t'=>''];return (($bi['c']??0)<=>($ai['c']??0))?:strcmp((string)($bi['t']??''),(string)($ai['t']??''));};
