<?php if($cUnmatched||$cSuggested||$cPlanUnmatched||$cPlanSuggested):?><div class="room-unmatched" style="margin-top:12px" data-code-sortbox><h3 style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">🔍 <?=$seenLabel?> görülen kodlar · tüm ürünler<select class="code-sort" style="font-size:11px;padding:3px 6px;border:1px solid #d8ded8;border-radius:4px;background:#fff;color:#10211f"><option value="c">En sık görülen ↑</option><option value="t">Son görülme ↑</option></select></h3><p class="conn-hint">Bu bağlantıdan gelen son <?=$seenLabel?> görülen dış oda ve fiyat planı kodlarının durumu (ürün seçilmeden, tüm ürünler). <b>Eşlenmemiş oda</b> (kırmızı nokta): hiçbir oda tipine bağlı değil; <b>eşlenmemiş plan</b> (mavi nokta): hiçbir fiyat planına bağlı değil — veri yazılmaz; <b>otomatik önerilen</b> (turuncu nokta): onay bekliyor. Eşleştirme ve onay bölüm 3'te yapılır.</p><div class="room-unmatched-codes"><?php foreach($cUnmatched as $uc=>$uv):?><span class="code-chip-wrap" data-c="<?=(int)$uv['c']?>" data-t="<?=$uv['t'] ? (int)strtotime((string)$uv['t']) : 0?>"><button type="button" class="conn-code-chip" data-conn="<?=(int)$c['id']?>" data-prop="<?=(int)($uv['p']??0)?>" data-room="<?=(int)($cBestRoom[$uc]??0)?>" data-code="<?=htmlspecialchars($uc)?>" title="Eşlenmemiş kanal oda kodu — <?=(int)$uv['c']?> işlemde görüldü · son görülme: #<?=(int)($uv['lid']??0)?> <?= $uv['t'] ? htmlspecialchars(date('d.m H:i',strtotime((string)$uv['t']))) : '—' ?> · tıkla: son webhook kaydını göster"><span class="room-um-dot" style="background:#b0301a"></span><?=htmlspecialchars($uc)?> <small>eşlenmemiş · <?=(int)$uv['c']?> tekrar · son görülme #<?=(int)($uv['lid']??0)?> <?= $uv['t'] ? htmlspecialchars(date('d.m H:i',strtotime((string)$uv['t']))) : '—' ?></small></button><button type="button" class="chip-action" data-act="flow" title="Bölüm 3'te hızlı eşleştirme başlat">⚡</button></span><?php endforeach;?><?php foreach($cSuggested as $scode=>$sm):$sv=$cSeenInfo[$scode]??null;?><span class="code-chip-wrap" data-c="<?=(int)($sv['c']??0)?>" data-t="<?= $sv && !empty($sv['t']) ? (int)strtotime((string)$sv['t']) : 0?>"><button type="button" class="conn-code-chip" data-conn="<?=(int)$c['id']?>" data-prop="<?=(int)($sm['property_id']??0)?>" data-code="<?=htmlspecialchars($scode)?>" title="Öneri: <?=htmlspecialchars($sm['room_name']??('#'.(int)$sm['room_type_id']))?> · <?=htmlspecialchars($sm['property_name']??'')?> · <?=(int)($sv['c']??0)?> tekrar · son görülme #<?=(int)($sv['lid']??0)?> <?= $sv && !empty($sv['t'])?htmlspecialchars(date('d.m H:i',strtotime((string)$sv['t']))):'—' ?> · tıkla: son webhook kaydını göster"><span class="room-um-dot" style="background:#b26a00"></span><?=htmlspecialchars($scode)?> <small>→ <?=htmlspecialchars($sm['room_name']??('#'.(int)$sm['room_type_id']))?><?= $sm['suggestion_score']!==null?' (%'.(int)$sm['suggestion_score'].')':'' ?> · <?=(int)($sv['c']??0)?> tekrar · son görülme #<?=(int)($sv['lid']??0)?> <?= $sv && !empty($sv['t'])?htmlspecialchars(date('d.m H:i',strtotime((string)$sv['t']))):'' ?></small></button><button type="button" class="chip-action" data-act="flow" title="Bölüm 3'te hızlı eşleştirme/onay başlat">⚡</button></span><?php endforeach;?><?php foreach($cPlanUnmatched as $pc=>$pv):?><span class="code-chip-wrap" data-c="<?=(int)$pv['c']?>" data-t="<?=$pv['t'] ? (int)strtotime((string)$pv['t']) : 0?>"><button type="button" class="conn-code-chip-plan" data-conn="<?=(int)$c['id']?>" data-prop="<?=(int)($pv['p']??0)?>" data-code="<?=htmlspecialchars($pc)?>" title="Eşlenmemiş kanal fiyat planı kodu — <?=(int)$pv['c']?> işlemde görüldü · son görülme: #<?=(int)($pv['lid']??0)?> <?= $pv['t'] ? htmlspecialchars(date('d.m H:i',strtotime((string)$pv['t']))) : '—' ?> · tıkla: son webhook kaydını göster"><span class="room-um-dot" style="background:#2b4a7a"></span><?=htmlspecialchars($pc)?> <small>eşlenmemiş plan · <?=(int)$pv['c']?> tekrar · son görülme #<?=(int)($pv['lid']??0)?> <?= $pv['t'] ? htmlspecialchars(date('d.m H:i',strtotime((string)$pv['t']))) : '—' ?></small></button><button type="button" class="chip-action" data-act="flow" title="Bölüm 3'te hızlı eşleştirme başlat">⚡</button></span><?php endforeach;?><?php foreach($cPlanSuggested as $psc=>$psm):$psv=$cPlanSeenInfo[$psc]??null;?><span class="code-chip-wrap" data-c="<?=(int)($psv['c']??0)?>" data-t="<?= $psv && !empty($psv['t']) ? (int)strtotime((string)$psv['t']) : 0?>"><button type="button" class="conn-code-chip-plan" data-conn="<?=(int)$c['id']?>" data-prop="<?=(int)($psm['property_id']??0)?>" data-code="<?=htmlspecialchars($psc)?>" title="Plan önerisi: <?=htmlspecialchars($psm['plan_name']??('#'.(int)$psm['rate_plan_id']))?> · <?=htmlspecialchars($psm['property_name']??'')?> · <?=(int)($psv['c']??0)?> tekrar · son görülme #<?=(int)($psv['lid']??0)?> <?= $psv && !empty($psv['t'])?htmlspecialchars(date('d.m H:i',strtotime((string)$psv['t']))):'—' ?> · tıkla: son webhook kaydını göster"><span class="room-um-dot" style="background:#b26a00"></span><?=htmlspecialchars($psc)?> <small>→ <?=htmlspecialchars($psm['plan_name']??('#'.(int)$psm['rate_plan_id']))?><?= $psm['suggestion_score']!==null?' (%'.(int)$psm['suggestion_score'].')':'' ?> · <?=(int)($psv['c']??0)?> tekrar · son görülme #<?=(int)($psv['lid']??0)?> <?= $psv && !empty($psv['t'])?htmlspecialchars(date('d.m H:i',strtotime((string)$psv['t']))):'' ?></small></button><button type="button" class="chip-action" data-act="flow" title="Bölüm 3'te hızlı eşleştirme/onay başlat">⚡</button></span><?php endforeach;?><div class="room-verify-result" id="conn-verify-<?=(int)$c['id']?>" hidden></div></div></div><?php endif;?><p class="conn-hint">Kanal tarafına bildirimler için bu webhook adresini verin. Bağlantı aktif olduğunda gönderilen JSON bildirimleri işlem günlüğünde görünür.</p></article><?php endforeach;?></section>
<section class="next-module"><h2>2. Ürün eşleştirmesi</h2><p>Bağlantı aktifleştirilmeden önce NEXUS ürününüzü kanalın tesis koduna bağlayın. Oda eşleştirmeleri sonraki adımda (bölüm 3) yapılır.</p><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="property_map"><div class="form-row"><label>Kanal<select name="connection_id"><?php foreach($connections as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['display_name'])?></option><?php endforeach;?></select></label><label>NEXUS ürünü<select name="property_id"><?php foreach($properties as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label><label>Kanal ürün kodu<input name="external_property_id" required></label></div><button>Eşleştirmeyi kaydet</button></form><?php foreach($mappings as $m):?><p><b><?=htmlspecialchars($m['display_name'])?></b> · <?=htmlspecialchars($m['property_name'])?> → <?=htmlspecialchars($m['external_property_id'])?></p><?php endforeach;?></section>
<section class="next-module" id="sec-room-map"><h2>3. Oda eşleştirmesi<?php if(($pendingSug+$pendingPlanSug)>0):?><span class="map-pending-badge" style="margin-left:8px;vertical-align:middle" title="Onay bekleyen oda / fiyat planı eşleştirme önerileri — aşağıda onaylayın">⏳ <?=(int)($pendingSug+$pendingPlanSug)?> onay bekleyen</span><?php endif;?></h2><button type="button" class="room-bulk-test-btn" title="Bölümdeki tüm oda eşleştirmelerini (onay bekleyen öneriler dahil) tek tek test eder ve özet rapor gösterir">🔬 Tüm eşleştirmeleri test et</button><div class="room-bulk-test-result" hidden></div><p>Kanalın webhook bildirimlerinde gönderdiği <b>dış oda kodu</b> ile NEXUS <b>oda/birim tipi + fiyat planı</b> çiftini aynı satırda eşleştirin; plan "İlk aktif plan" bırakılırsa varsayılan kullanılır. Fiyat, kontenjan, kısıt ve rezervasyon bildirimleri doğru oda tipine ve plana yazılır. <b>Tanınmayan kod</b> (kontrol merkezi ayarı açıkken) ilk aktif oda tipine yazılmaz — aşağıda <b>onay bekleyen öneri</b> olarak listelenir; onaylanınca o koda ait satırlar yazılmaya başlar.</p><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="room_map_edit"><div class="form-row"><label>Kanal<select name="connection_id"><?php foreach($connections as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['display_name'])?></option><?php endforeach;?></select></label><label>NEXUS ürünü<select name="property_id"><?php foreach($properties as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label></div><button>Eşleştirmeleri düzenle →</button></form><?php if(!empty($roomEdit)): $rmq=$pdo->prepare('SELECT id, room_type_id, rate_plan_id, external_room_id, status, suggestion_count, suggested_at, suggestion_score, approved_by_type, approved_by_name, approved_at FROM channel_room_mappings WHERE channel_connection_id=? AND property_id=? ORDER BY (status=\'suggested\') DESC, id');$rmq->execute([$roomEdit['connection_id'],$roomEdit['property_id']]);$mapByRoom=[];$mapPlanByRoom=[];$mapApprovedBy=[];$suggestions=[];$suggestedRooms=[];foreach($rmq->fetchAll() as $mr){$mapByRoom[(int)$mr['room_type_id']]=$mr['external_room_id'];$mapPlanByRoom[(int)$mr['room_type_id']]=$mr['rate_plan_id']!==null?(int)$mr['rate_plan_id']:0;$mapApprovedBy[(int)$mr['room_type_id']]=($mr['status']==='confirmed' && !empty($mr['approved_at']))?((string)($mr['approved_by_name']??'')!==''?(string)$mr['approved_by_name']:'—').' · '.date('d.m H:i',strtotime((string)$mr['approved_at'])):'';if($mr['status']==='suggested'){$suggestions[]=$mr;$suggestedRooms[(int)$mr['room_type_id']]=true;}}$rq=$pdo->prepare('SELECT id,name,status FROM room_types WHERE property_id=? ORDER BY name');$rq->execute([$roomEdit['property_id']]);$roomRows=$rq->fetchAll();$roomNames=[];foreach($roomRows as $rr)$roomNames[(int)$rr['id']]=$rr['name'];$plq=$pdo->prepare("SELECT id,name,currency FROM rate_plans WHERE property_id=? AND status='active' ORDER BY id");$plq->execute([$roomEdit['property_id']]);$plans=$plq->fetchAll();$planNamesById=[];foreach($plans as $pl)$planNamesById[(int)$pl['id']]=$pl['name'];$connName='';foreach($connections as $c)if((int)$c['id']===(int)$roomEdit['connection_id'])$connName=$c['display_name'];?><?php if($suggestions):?><div class="room-suggestions"><h3>⏳ Onay bekleyen eşleştirme önerileri</h3><p class="conn-hint">Webhook'ta tanınmayan dış oda kodu geldi; veri onaylanana kadar yazılmadı. <b>Onayla</b> → kod bundan sonra seçili oda tipine yazılır; <b>Reddet</b> → öneri düşer. Farklı bir oda tipine bağlamak için aşağıdaki formdan kod yazıp kaydedin (otomatik onaylanır).</p><?php foreach($suggestions as $sg):?><div class="room-suggestion-wrap" data-verify-box><div class="room-suggestion-row"><div><b><?=htmlspecialchars($sg['external_room_id'])?></b><span>→ <?=htmlspecialchars($roomNames[(int)$sg['room_type_id']]??('#'.(int)$sg['room_type_id']))?><?= ($sg['suggestion_score']??null)!==null?' <b style="color:#b26a00">%'.(int)$sg['suggestion_score'].' benzerlik</b>':'' ?><?= (int)($sg['rate_plan_id']??0)>0 ? ' · plan: '.htmlspecialchars($planNamesById[(int)$sg['rate_plan_id']]??('#'.(int)$sg['rate_plan_id'])) : '' ?> · <?=(int)$sg['suggestion_count']?> bildirim · son öneri <?=htmlspecialchars((string)($sg['suggested_at']??''))?></span></div><div class="room-suggestion-actions"><button type="button" class="room-verify-btn" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($sg['external_room_id'])?>">Doğrula</button><button type="button" class="room-test-btn" data-suggest="1" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($sg['external_room_id'])?>" title="Onaylamadan önce hedefi test et: eşleşme/plan/kur kontrolü + örnek yük — hedef doğrulanınca Onayla yeşil işaretlenir">🔍 Test et</button><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="room_map_approve"><input type="hidden" name="mapping_id" value="<?=(int)$sg['id']?>"><input type="hidden" name="connection_id" value="<?=(int)$roomEdit['connection_id']?>"><input type="hidden" name="property_id" value="<?=(int)$roomEdit['property_id']?>"><button class="room-approve-btn">Onayla ✓</button></form><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="room_map_reject"><input type="hidden" name="mapping_id" value="<?=(int)$sg['id']?>"><input type="hidden" name="connection_id" value="<?=(int)$roomEdit['connection_id']?>"><input type="hidden" name="property_id" value="<?=(int)$roomEdit['property_id']?>"><button class="danger-btn">Reddet ✕</button></form></div></div><div class="room-verify-result" hidden></div></div><?php endforeach;?></div><?php endif;?><?php $seen=$pdo->prepare("SELECT request_payload, created_at FROM channel_sync_logs WHERE channel_connection_id=? AND property_id=? AND direction='pull' AND request_payload IS NOT NULL".$seenFilter." ORDER BY id DESC LIMIT ?");$seen->execute([$roomEdit['connection_id'],$roomEdit['property_id'],$seenWindow]);$seenCodes=[];foreach($seen->fetchAll() as $sl){$dec=json_decode((string)$sl['request_payload'],true);if(!is_array($dec)||!isset($dec['entries'])||!is_array($dec['entries']))continue;foreach($dec['entries'] as $en){if(is_array($en)&&isset($en['external_room_id'])&&trim((string)$en['external_room_id'])!==''){$code=trim((string)$en['external_room_id']);if(!isset($seenCodes[$code]))$seenCodes[$code]=['c'=>0,'t'=>(string)$sl['created_at']];$seenCodes[$code]['c']++;}}}$unmatched=[];$autoSuggested=[];$codeTarget=[];if($seenCodes){$pl=$pdo->prepare('SELECT id, external_room_id, room_type_id, status, suggestion_score FROM channel_room_mappings WHERE channel_connection_id=? AND property_id=?');$pl->execute([$roomEdit['connection_id'],$roomEdit['property_id']]);$mapInfo=[];foreach($pl->fetchAll() as $mc)$mapInfo[$mc['external_room_id']]=$mc;foreach(array_keys($seenCodes) as $code){if(!isset($mapInfo[$code])){$unmatched[$code]=$seenCodes[$code];$codeTarget[$code]=0;continue;}if($mapInfo[$code]['status']==='suggested'){$autoSuggested[$code]=$seenCodes[$code];$codeTarget[$code]=(int)$mapInfo[$code]['room_type_id'];}}}uasort($unmatched,function($a,$b){return (($b['c']??0)<=>($a['c']??0))?:strcmp((string)($b['t']??''),(string)($a['t']??''));});uasort($autoSuggested,function($a,$b){return (($b['c']??0)<=>($a['c']??0))?:strcmp((string)($b['t']??''),(string)($a['t']??''));});?><?php if($unmatched||$autoSuggested):?><div class="room-unmatched"><h3>🔍 <?=$seenLabel?> görülen eşleşmemiş / otomatik eşlenen kodlar</h3><p class="conn-hint">Bu kanaldan gelen son <?=$seenLabel?> görülen dış kodların durumu. <b>Eşlenmemiş</b> (kırmızı nokta): hiçbir oda tipine bağlı değil; <b>otomatik önerilen</b> (turuncu nokta): onay bekliyor, veri yazılmıyor. <b>Öneri chip'ine tıklayınca doğrudan onaylanır</b> — kod artık seçili oda tipine yazılır; eşlenmemiş chip'ine tıklayınca aşağıdaki formda ilgili oda tipinin kodu dolar (kaydederseniz otomatik onaylanır). ⧉ ile doldurma, 🔍 ile son kayıt görüntülenir.</p><div class="room-unmatched-codes"><?php foreach($unmatched as $uc=>$uv):?><span class="code-chip-wrap"><button type="button" class="room-unmatched-chip" data-room="0" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($uc)?>" title="Eşlenmemiş — <?=(int)$uv['c']?> işlemde görüldü · tıkla: form alanına doldur"><span class="room-um-dot" style="background:#b0301a"></span><?=htmlspecialchars($uc)?> <small>eşlenmemiş · <?=(int)$uv['c']?> işlem · son <?= $uv['t'] ? htmlspecialchars(date('d.m H:i',strtotime((string)$uv['t']))) : '—' ?></small></button><button type="button" class="chip-action" data-act="fill" data-room="0" title="Kodu bir oda tipinin alanına doldur">⧉</button><button type="button" class="chip-action" data-act="verify" title="Son webhook kaydını göster">🔍</button></span><?php endforeach;?><?php foreach($autoSuggested as $ac=>$av):$tgt=$codeTarget[$ac]??0;$sc=$mapInfo[$ac]['suggestion_score']??null;?><span class="code-chip-wrap"><button type="button" class="room-unmatched-chip" data-room="<?=(int)$tgt?>" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($ac)?>" data-map="<?=(int)($mapInfo[$ac]['id']??0)?>" title="Öneri: <?=htmlspecialchars($roomNames[$tgt]??('#'.(int)$tgt))?> · tıkla: öneriyi doğrudan onayla"><span class="room-um-dot" style="background:#b26a00"></span><?=htmlspecialchars($ac)?> <small>→ <?=htmlspecialchars($roomNames[$tgt]??('#'.(int)$tgt))?> (öneri<?= $sc!==null?' · %'.(int)$sc:'' ?>) · <?=(int)$av['c']?> işlem<?= !empty($av['t'])?' · son '.htmlspecialchars(date('d.m H:i',strtotime((string)$av['t']))):'' ?></small></button><button type="button" class="chip-action" data-act="fill" data-room="<?=(int)$tgt?>" title="Kodu bu oda tipinin alanına doldur">⧉</button><button type="button" class="chip-action" data-act="verify" title="Son webhook kaydını göster">🔍</button></span><?php endforeach;?><div class="room-verify-result" id="room-list-verify" hidden></div></div></div><?php endif;?><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="room_map_save"><input type="hidden" name="connection_id" value="<?=(int)$roomEdit['connection_id']?>"><input type="hidden" name="property_id" value="<?=(int)$roomEdit['property_id']?>"><h3><?=htmlspecialchars($connName)?> → oda eşleştirmeleri</h3><p class="conn-hint">Her NEXUS oda tipine kanalın kullandığı dış kodu yazın ve hedef fiyat planını seçin; boş bırakılan satır eşleşmeyi kaldırır, plan boşsa ilk aktif plan kullanılır. Aynı dış kod iki oda tipine verilemez; buradan kaydedilen her satır onaylı kabul edilir.</p><?php if(!empty($roomEdit['quick_code'])):?><div class="room-quick-match" data-quick-box<?= !empty($roomEdit['quick_code']) ? '' : ' style="display:none"' ?>><b>⚡ Hızlı eşleştir:</b> <code data-quick-code><?=htmlspecialchars((string)($roomEdit['quick_code']??''))?></code><select id="quick-room-select" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>"><?php foreach($roomRows as $qr):?><option value="<?=(int)$qr['id']?>" <?= (int)($roomEdit['quick_room']??0)===(int)$qr['id']?'selected':'' ?>><?=htmlspecialchars($qr['name'])?><?= $qr['status']==='active'?'':' ('.$qr['status'].')' ?></option><?php endforeach;?></select><select id="quick-plan-select" title="Test ve kayıt için hedef fiyat planı (boş = ilk aktif plan)"><option value="0">İlk aktif plan</option><?php foreach($plans as $qp):?><option value="<?=(int)$qp['id']?>"><?=htmlspecialchars($qp['name'].' · '.$qp['currency'])?></option><?php endforeach;?></select><button type="button" id="quick-match-btn">Kodu oda tipine doldur →</button><button type="button" id="quick-test-btn" title="Kaydetmeden test: kod seçili oda tipi + plana yazılırsa NEXUS tarafında doğru plana gider mi, kur var mı — anında kontrol eder">🔍 Kaydetmeden test et</button><div class="room-verify-result" id="quick-test-result" hidden></div><span class="conn-hint">Kod seçili oda tipinin alanına dolar; aşağıdaki "Eşleştirmeleri kaydet" ile onaylayın. "Kaydetmeden test et" ile önce hedefi doğrulayın (kur yoksa uyarır). İptal için kutuyu kapatın.</span></div><?php endif;?><?php foreach($roomRows as $r):$rowCode=(string)($mapByRoom[(int)$r['id']]??'');$rowApproved=(string)($mapApprovedBy[(int)$r['id']]??'');$simPool=$unmatched+$autoSuggested;$simHits=[];foreach($simPool as $simCode=>$simInfo){$simSc=(int)round(name_similarity((string)$simCode,(string)$r['name'])*100);if($simSc>=30)$simHits[(string)$simCode]=$simSc;}arsort($simHits);$simHits=array_slice($simHits,0,3,true);?><div class="room-map-wrap" data-verify-box><div class="room-map-row"><label><?=htmlspecialchars($r['name'])?><?= $r['status']==='active'?'':' <small>('.$r['status'].')</small>' ?><?= isset($suggestedRooms[(int)$r['id']])?' <small class="sug-badge">öneri bekliyor</small>':'' ?><?= $rowApproved!==''?' <small class="map-approved-badge" title="Bu eşleştirmeyi onaylayan">✓ '.htmlspecialchars($rowApproved).'</small>':'' ?></label><input id="room-code-<?=(int)$r['id']?>" name="rooms[<?=(int)$r['id']?>]" value="<?=htmlspecialchars($rowCode)?>" placeholder="Kanal oda kodu — Örn. OTA-DELUXE"><?php if($simHits):?><span class="room-sim-hits" style="display:inline-flex;gap:6px;align-items:center;flex-wrap:wrap;font-size:11px;color:#64716d">Öneri:<?php foreach($simHits as $simCode=>$simSc):?><button type="button" class="room-sim-chip" data-room="<?=(int)$r['id']?>" data-code=