Suggestions):?><div class="room-suggestions" style="margin-top:18px"><h3>⏳ Onay bekleyen fiyat planı eşleştirme önerileri</h3><p class="conn-hint">Webhook'ta tanınmayan dış fiyat planı kodu geldi; veri onaylanana kadar yazılmadı. <b>Onayla</b> → kod bundan sonra seçili fiyat planına yazılır; <b>Reddet</b> → öneri düşer. Farklı bir plana bağlamak için aşağıdaki formdan kodu yazıp kaydedin (otomatik onaylanır).</p><?php foreach($planSuggestions as $ps):?><div class="room-suggestion-wrap" data-verify-box><div class="room-suggestion-row"><div><b><?=htmlspecialchars($ps['external_rate_plan_id'])?></b><span>→ <?=htmlspecialchars($planNamesById[(int)$ps['rate_plan_id']]??('#'.(int)$ps['rate_plan_id']))?><?= ($ps['suggestion_score']??null)!==null?' <b style="color:#b26a00">%'.(int)$ps['suggestion_score'].' benzerlik</b>':'' ?> · <?=(int)$ps['suggestion_count']?> bildirim · son öneri <?=htmlspecialchars((string)($ps['suggested_at']??''))?></span></div><div class="room-suggestion-actions"><button type="button" class="plan-test-btn" data-suggest="1" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($ps['external_rate_plan_id'])?>" title="Onaylamadan önce hedefi test et: dış plan kodu doğru NEXUS planına yazılır mı? — hedef doğrulanınca Onayla yeşil işaretlenir">🔍 Test et</button><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="plan_map_approve"><input type="hidden" name="mapping_id" value="<?=(int)$ps['id']?>"><input type="hidden" name="connection_id" value="<?=(int)$roomEdit['connection_id']?>"><input type="hidden" name="property_id" value="<?=(int)$roomEdit['property_id']?>"><button class="room-approve-btn">Onayla ✓</button></form><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="plan_map_reject"><input type="hidden" name="mapping_id" value="<?=(int)$ps['id']?>"><input type="hidden" name="connection_id" value="<?=(int)$roomEdit['connection_id']?>"><input type="hidden" name="property_id" value="<?=(int)$roomEdit['property_id']?>"><button class="danger-btn">Reddet ✕</button></form></div><div class="room-verify-result" hidden></div></div><?php endforeach;?></div><?php endif;?><?php $planSeenQ=$pdo->prepare("SELECT request_payload, created_at FROM channel_sync_logs WHERE channel_connection_id=? AND property_id=? AND direction='pull' AND request_payload IS NOT NULL".$seenFilter." ORDER BY id DESC LIMIT ?");$planSeenQ->execute([$roomEdit['connection_id'],$roomEdit['property_id'],$seenWindow]);$planSeen=[];foreach($planSeenQ->fetchAll() as $psl){$pdec=json_decode((string)$psl['request_payload'],true);if(!is_array($pdec)||!isset($pdec['entries'])||!is_array($pdec['entries']))continue;foreach($pdec['entries'] as $pen){if(is_array($pen)&&isset($pen['external_rate_plan_id'])&&trim((string)$pen['external_rate_plan_id'])!==''){$pcode=trim((string)$pen['external_rate_plan_id']);if(!isset($planSeen[$pcode]))$planSeen[$pcode]=['c'=>0,'t'=>(string)$psl['created_at']];$planSeen[$pcode]['c']++;}}}$planUnmatched=[];$planAutoSug=[];$planCodeTarget=[];$planMapInfo=[];if($planSeen){$plm=$pdo->prepare('SELECT id, rate_plan_id, external_rate_plan_id, status, suggestion_score FROM channel_rate_plan_mappings WHERE channel_connection_id=? AND property_id=?');$plm->execute([$roomEdit['connection_id'],$roomEdit['property_id']]);foreach($plm->fetchAll() as $pmc)$planMapInfo[$pmc['external_rate_plan_id']]=$pmc;foreach(array_keys($planSeen) as $pcode){if(!isset($planMapInfo[$pcode])){$planUnmatched[$pcode]=$planSeen[$pcode];$planCodeTarget[$pcode]=0;continue;}if($planMapInfo[$pcode]['status']==='suggested'){$planAutoSug[$pcode]=$planSeen[$pcode];$planCodeTarget[$pcode]=(int)$planMapInfo[$pcode]['rate_plan_id'];}}}uasort($planUnmatched,function($a,$b){return (($b['c']??0)<=>($a['c']??0))?:strcmp((string)($b['t']??''),(string)($a['t']??''));});uasort($planAutoSug,function($a,$b){return (($b['c']??0)<=>($a['c']??0))?:strcmp((string)($b['t']??''),(string)($a['t']??''));});?><?php if($planUnmatched||$planAutoSug):?><div class="room-unmatched" style="margin-top:18px"><h3>🔍 <?=$seenLabel?> görülen eşleşmemiş / otomatik eşlenen fiyat planı kodları</h3><p class="conn-hint">Bu kanaldan gelen son <?=$seenLabel?> görülen dış fiyat planı kodlarının durumu. <b>Eşlenmemiş</b> (kırmızı nokta): hiçbir NEXUS planına bağlı değil; <b>otomatik önerilen</b> (turuncu nokta): onay bekliyor, veri yazılmıyor. <b>Öneri chip'ine tıklayınca doğrudan onaylanır</b> — kod artık seçili plana yazılır; 🔍 ile dış plan kodunun doğru NEXUS planına yazılıp yazılmayacağı anında test edilir.</p><div class="room-unmatched-codes"><?php foreach($planUnmatched as $puc=>$puv):?><span class="code-chip-wrap"><button type="button" class="plan-unmatched-chip" data-map="0" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($puc)?>" title="Eşlenmemiş — <?=(int)$puv['c']?> işlemde görüldü · 🔍 ile test et"><span class="room-um-dot" style="background:#b0301a"></span><?=htmlspecialchars($puc)?> <small>eşlenmemiş · <?=(int)$puv['c']?> işlem · son <?= $puv['t'] ? htmlspecialchars(date('d.m H:i',strtotime((string)$puv['t']))) : '—' ?></small></button><button type="button" class="chip-action" data-act="verify" data-kind="plan" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($puc)?>" title="Dış plan kodunu test et — doğru NEXUS planına yazılır mı?">🔍</button></span><?php endforeach;?><?php foreach($planAutoSug as $pac=>$pav):$ptgt=$planCodeTarget[$pac]??0;$psc=$planMapInfo[$pac]['suggestion_score']??null;?><span class="code-chip-wrap"><button type="button" class="plan-unmatched-chip" data-map="<?=(int)($planMapInfo[$pac]['id']??0)?>" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($pac)?>" title="Öneri: <?=htmlspecialchars($planNamesById[$ptgt]??('#'.(int)$ptgt))?> · tıkla: öneriyi doğrudan onayla"><span class="room-um-dot" style="background:#b26a00"></span><?=htmlspecialchars($pac)?> <small>→ <?=htmlspecialchars($planNamesById[$ptgt]??('#'.(int)$ptgt))?> (öneri<?= $psc!==null?' · %'.(int)$psc:'' ?>) · <?=(int)$pav['c']?> işlem<?= !empty($pav['t'])?' · son '.htmlspecialchars(date('d.m H:i',strtotime((string)$pav['t']))):'' ?></small></button><button type="button" class="chip-action" data-act="verify" data-kind="plan" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($pac)?>" title="Dış plan kodunu test et — hedef doğrulanınca onaylayın">🔍</button></span><?php endforeach;?><div class="room-verify-result" id="plan-list-verify" hidden></div></div></div><?php endif;?><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="plan_map_save"><input type="hidden" name="connection_id" value="<?=(int)$roomEdit['connection_id']?>"><input type="hidden" name="property_id" value="<?=(int)$roomEdit['property_id']?>"><h3><?=htmlspecialchars($connName)?> → fiyat planı eşleştirmeleri</h3><p class="conn-hint">Webhook yükü <code>external_rate_plan_id</code> gönderdiğinde fiyat/kontenjan buradaki eşleştirmeyle NEXUS planına yazılır; boş satır eşleşmeyi kaldırır. Kodu bilinmeyen plan onay akışına girer (yukarıdaki öneriler). Buradan kaydedilen her satır onaylı kabul edilir.</p><?php foreach($plans as $pl):$pc=(string)($planMapByPlan[(int)$pl['id']]??'');?><div class="room-map-row" data-verify-box><label><?=htmlspecialchars($pl['name'])?> · <?=htmlspecialchars($pl['currency'])?><?= isset($suggestedPlans[(int)$pl['id']])?' <small class="sug-badge">öneri bekliyor</small>':'' ?></label><input name="plan_codes[<?=(int)$pl['id']?>]" value="<?=htmlspecialchars($pc)?>" placeholder="Kanal fiyat planı kodu — Örn. OTA-BAR"><?php if($pc!==''):?><button type="button" class="plan-test-btn" data-conn="<?=(int)$roomEdit['connection_id']?>" data-prop="<?=(int)$roomEdit['property_id']?>" data-code="<?=htmlspecialchars($pc)?>" title="Dış plan kodu doğru NEXUS planına yazılıyor mu — anında test et">Test et</button><?php endif;?><div class="room-verify-result" hidden></div></div><?php endforeach;?><button>Plan eşleştirmelerini kaydet →</button></form><?php $blq=$pdo->prepare('SELECT code_type,external_code,rejected_at,rejected_by FROM channel_mapping_blacklist WHERE channel_connection_id=? ORDER BY rejected_at DESC LIMIT 20');$blacklistedRows=[];try{$blq->execute([$roomEdit['connection_id']]);$blacklistedRows=$blq->fetchAll();}catch(Throwable $e){}?><?php if($blacklistedRows):?><div class="room-suggestions" style="margin-top:18px"><h3>🚫 Karalistede (reddedilen kodlar)</h3><p class="conn-hint">Bu kodlar reddedildi; webhook tekrar gelse de yeniden öneri oluşturulmaz ve veri yazılmaz. Kodu elle eşleştirmek (yukarıdaki form) karalisteyi otomatik temizler; ya da tek tek kaldırabilirsiniz.</p><?php foreach($blacklistedRows as $bk):?><div class="room-suggestion-row"><div><b><?=htmlspecialchars($bk['external_code'])?></b><span>· <?=$bk['code_type']==='plan'?'fiyat planı':'oda'?> · reddedildi: <?=htmlspecialchars(mb_substr((string)$bk['rejected_at'],0,16))?><?= !empty($bk['rejected_by'])?' · '.htmlspecialchars((string)$bk['rejected_by']):'' ?></span></div><div class="room-suggestion-actions"><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="blacklist_remove"><input type="hidden" name="connection_id" value="<?=(int)$roomEdit['connection_id']?>"><input type="hidden" name="property_id" value="<?=(int)$roomEdit['property_id']?>"><input type="hidden" name="code_type" value="<?=htmlspecialchars($bk['code_type'])?>"><input type="hidden" name="external_code" value="<?=htmlspecialchars($bk['external_code'])?>"><button>Kaldır</button></form></div></div><?php endforeach;?></div><?php endif;?><?php endif;?></section>
<section class="next-module"><h2>4. Gönderim kuyruğu & işlem günlüğü <small style="font-size:12px;color:#64716d;font-weight:normal">(son <?=$seenLabel?> — üstteki pencereden ayarlanır)</small></h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="queue"><div class="form-row"><label>Kanal<select name="connection_id"><?php foreach($connections as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['display_name'])?></option><?php endforeach;?></select></label><label>Gönderim türü<select name="scope"><option value="availability">Kontenjan</option><option value="rates">Fiyat</option><option value="restrictions">Kısıtlar</option><option value="content">İlan içeriği</option></select></label></div><button>Manuel senkronizasyon başlat</button></form><?php foreach($logs as $log):$logFx=json_decode((string)($log['fx_audit']??'[]'),true);$logUrl=(isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.(string)($_SERVER['HTTP_HOST']??'').(string)($_SERVER['REQUEST_URI']??'/tedarikci/dagitim-merkezi.php').'#sync-log-'.(int)$log['id'];$logPayload=trim((string)($log['request_payload']??''));if($logPayload!==''){$decP=json_decode($logPayload,true);$logPretty=json_encode($decP,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if(!is_string($logPretty)||$logPretty==='null')$logPretty=$logPayload;}else{$logPretty='';}$retryAttempts=(int)($log['attempt_count']??0);$retryMax=max(2,min(10,(int)platform_setting('channel_webhook_max_retries',3)));$retryInfo='';if($log['status']==='failed'){if($retryAttempts>=$retryMax){$retryInfo='<span class="retry-chip retry-exhausted" title="Maksimum '.$retryMax.' denemeye ulaşıldı — bu yük bir daha otomatik yeniden denenmez">deneme '.$retryAttempts.'/'.$retryMax.' · yeniden denenmez</span>';}else{$backoffSec=$retryAttempts===1?300:($retryAttempts===2?900:60);$baseTs=$log['completed_at']?strtotime((string)$log['completed_at']):time();$nextTs=$baseTs+$backoffSec;$nextStr=$nextTs<=time()?'hemen (kuyruğa alınmak üzere)':date('d.m H:i',$nextTs);$retryInfo='<span class="retry-chip retry-pending" title="Geri adım: '.round($backoffSec/60).' dk — başarısızlık sonrası beklenir">deneme '.$retryAttempts.'/'.$retryMax.' · sonraki deneme: '.$nextStr.'</span>';}}else{$retryInfo='<span class="retry-chip retry-done">deneme '.$retryAttempts.'/'.$retryMax.'</span>';}?><p id="sync-log-<?=(int)$log['id']?>"><button type="button" class="ical-copy-btn sync-log-copy" data-copy="<?=htmlspecialchars($logUrl)?>" title="Doğrudan bağlantıyı kopyala — #sync-log-<?=(int)$log['id']?> (sayfa + satıra odaklanma)" style="border:1px solid #d8ded8;background:#fff;border-radius:4px;padding:1px 6px;font-size:11px;cursor:pointer;margin-right:6px;vertical-align:middle">🔗 #sync-log-<?=(int)$log['id']?></button><?php if($logPretty!==''):?><button type="button" class="sync-log-json-toggle" data-logid="<?=(int)$log['id']?>" title="<?= $log['status']==='failed' ? 'Başarısız yükün ham JSON&#39;u — hata incelemesi' : 'Bu yükün ham JSON&#39;u — hata incelemesi' ?>" style="border:1px solid <?= $log['status']==='failed' ? '#b0301a' : '#d8ded8' ?>;background:<?= $log['status']==='failed' ? '#fdf3f2' : '#fff' ?>;color:<?= $log['status']==='failed' ? '#b0301a' : '#64716d' ?>;border-radius:4px;padding:1px 6px;font-size:11px;cursor:pointer;margin-right:6px;vertical-align:middle">📄 JSON</button><?php endif;?><b><?=htmlspecialchars($log['display_name'])?></b> · <?=htmlspecialchars($log['direction'])?> / <?=htmlspecialchars($log['scope'])?> · <strong><?=htmlspecialchars($log['status'])?></strong> · <?=htmlspecialchars($log['created_at'])?> <?=$retryInfo?><?php if(is_array($logFx))foreach($logFx as $lf):?><span class="fx-audit-badge" title="<?=htmlspecialchars((string)($lf['from']??'').'→'.(string)($lf['to']??'').' · '.(int)($lf['count']??0).' fiyat · kur '.(float)($lf['rate']??0).' · toplam '.number_format((float)($lf['converted_total']??0),2,',','.').' '.(string)($lf['to']??''))?>"><?=htmlspecialchars((string)($lf['from']??'').'→'.(string)($lf['to']??''))?> · <?=(int)($lf['count']??0)?> fiyat · kur <?=htmlspecialchars((string)($lf['rate']??''))?></span><?php endforeach;?><?= $log['error_message']?' · '.htmlspecialchars($log['error_message']):''?></p><?php if($logPretty!==''):?><div class="sync-log-json-panel" id="sync-log-json-<?=(int)$log['id']?>" hidden style="background:#0d1420;color:#c9d6e3;border-radius:6px;padding:10px 12px;margin:4px 0 10px;font-family:monospace;font-size:11.5px;white-space:pre-wrap;word-break:break-word;max-height:260px;overflow:auto"><pre style="margin:0;font:inherit;color:inherit"><?=htmlspecialchars($logPretty)?></pre></div><?php endif;?><?php endforeach;?></section><section class="next-module"><h2>5. Webhook test aracı</h2><p class="conn-hint">Token kopyalamadan kanal webhook akışını test edin: kanal + ürün + dış oda kodu + fiyat gönderin. Yük kuyruğa eklenir, işleyiciyle aynen uygulanır ve sonuç (takvim yazımı, kur dönüşümü dahil) anında aşağıda raporlanır. Kanalın gerçek tokenı sizin yerinize sunucuda kullanılır.</p><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="webhook_test"><div class="form-row"><label>Kanal<select name="connection_id"><?php foreach($connections as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['display_name'])?></option><?php endforeach;?></select></label><label>NEXUS ürünü<select name="property_id"><?php foreach($properties as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label></div><div class="form-row"><label>Dış oda kodu<input name="room_code" placeholder="Örn. OTA-STD" required></label><label>Fiyat<input type="number" step="0.01" min="0.01" name="price" placeholder="123.45" required></label><label>Para birimi<select name="currency"><option value="EUR">EUR</option><option value="USD">USD</option><option value="TRY">TRY</option><option value="GBP">GBP</option></select></label><label>Tarih<input type="date" name="test_date" value="<?=date('Y-m-d',strtotime('+60 days'))?>" required></label></div><button>▶ Test fiyatı gönder</button></form><?php if(!empty($webhookTest)):?><div class="wt-box <?= $webhookTest['ok']?'wt-ok':'wt-err' ?>"><?php if($webhookTest['ok']):?><p style="margin:0 0 6px"><b style="color:#2e7d32">✓ Test yükü uygulandı</b> — <?=htmlspecialchars($webhookTest['message'])?></p><?php else:?><p style="margin:0 0 6px"><b style="color:#b0301a">✗ Test yükü uygulanamadı</b> — <?=htmlspecialchars($webhookTest['message'])?></p><?php endif;?><?php if(!empty($webhookTest['fx_audit'])):?><?php foreach($webhookTest['fx_audit'] as $fx):?><p style="margin:2px 0;font-size:12px;color:#0d7a4a"><?=htmlspecialchars((string)($fx['from']??'').'→'.(string)($fx['to']??'').' · kur '.(string)($fx['rate']??'').' · '.(int)($fx['count']??0).' fiyat · '.(float)($fx['original_total']??0).' '.(string)($fx['from']??'').' → '.(float)($fx['converted_total']??0).' '.(string)($fx['to']??''))?></p><?php endforeach;?><?php endif;?><p style="margin:6px 0 0;font-size:12px">İşlem günlüğü: <a href="#sync-log-<?=(int)$webhookTest['log_id']?>" class="wt-log-link" data-wtid="<?=(int)$webhookTest['log_id']?>">log #<?=(int)$webhookTest['log_id']?> → bölüm 4</a></p></div><script>(function(){var a=document.querySelector('.wt-log-link');if(a){a.addEventListener('click',function(e){e.preventDefault();var r=document.getElementById('sync-log-'+this.getAttribute('data-wtid'));if(r){r.scrollIntoView({behavior:'smooth',block:'center'});r.classList.add('log-row-flash');setTimeout(function(){r.classList.remove('log-row-flash')},2200)}})}})();</script><?php endif;?></section><script>function fallbackCopy(text){var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy')}catch(e){}document.body.removeChild(ta)}document.querySelectorAll('.ical-copy-btn').forEach(function(b){if(!b.title)b.title=b.getAttribute('data-copy')||'';b.addEventListener('click',function(){var url=this.getAttribute('data-copy'),btn=this;function done(){btn.textContent='Kopyalandı ✓';btn.classList.add('copied');setTimeout(function(){btn.textContent='Kopyala';btn.classList.remove('copied')},1600)}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(url).then(done).catch(function(){fallbackCopy(url);done()})}else{fallbackCopy(url);done()}})});document.querySelectorAll('.sync-log-json-toggle').forEach(function(b){b.addEventListener('click',function(){var id=this.getAttribute('data-logid'),p=document.getElementById('sync-log-json-'+id),row=this.parentNode;if(!p)return;var open=p.hidden===false;p.hidden=open;if(!open){p.scrollIntoView({behavior:'smooth',block:'nearest'});row.classList.add('log-row-flash');setTimeout(function(){row.classList.remove('log-row-flash')},1800)}this.textContent=open?'📄 JSON':'📄 Gizle'})});function roomVerifyShow(res,conn,prop,code){if(!res)return;res.hidden=false;res.textContent='…';fetch('/nexustraveltech/api/supplier-room-verify.php?connection_id='+encodeURIComponent(conn)+'&property_id='+encodeURIComponent(prop)+'&code='+encodeURIComponent(code),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(d){if(!d.ok){res.textContent=d.message||'Hata';res.className='room-verify-result err';return;}if(!d.found){res.textContent=d.message||'Bu kod için webhook kaydı yok.';res.className='room-verify-result';return;}var e=d.entry||{},parts=['#'+d.log.id+' · '+d.log.scope+' · '+d.log.status+(d.log.error_message?' · hata: '+d.log.error_message:'')+' · '+d.log.created_at];if(e.date)parts.push('tarih: '+e.date);if(e.price!==undefined&&e.price!==null&&e.price!=='')parts.push('fiyat: '+e.price+(e.currency?' '+e.currency:''));if(e.allotment!==undefined&&e.allotment!==null)parts.push('kontenjan: '+e.allotment);if(e.stop_sale!==undefined)parts.push('satış kapalı: '+(e.stop_sale?'evet':'hayır'));if(e.min_stay!==undefined)parts.push('min konaklama: '+e.min_stay);if(e.max_stay!==undefined&&e.max_stay!==null)parts.push('max konaklama: '+e.max_stay);if(d.summary)parts.push(d.summary.applied_rows+' uygulandı · '+d.summary.skipped_rows+' atlandı (son '+d.summary.logs_seen+' işlem)');if(d.conversion){parts.push('dönüşüm (bu girdi): '+d.conversion.from+'→'+d.conversion.to+' · kur '+d.conversion.rate+' · '+d.conversion.original+' '+d.conversion.from+' → '+d.conversion.converted+' '+d.conversion.to);}if(d.plan){parts.push('hedef plan: '+d.plan.name+' · '+d.plan.currency+' ('+d.plan.source+')');}if(d.fx_audit&&d.fx_audit.length){var fx=d.fx_audit.map(function(f){return f.from+'→'+f.to+' · kur '+f.rate+(f.count>1?' · '+f.count+' fiyat':'')+' · '+f.original_total+' '+f.from+' → '+f.converted_total+' '+f.to;});parts.push('dönüşüm: '+fx.join('; '));}res.textContent=parts.join(' · ');res.className='room-verify-result'+(d.log.status==='failed'?' err':'');if(d.log.status==='failed'){var a=document.createElement('a');a.href='#sync-log-'+(d.log.id||0);a.className='verify-log-jump';a.textContent=' İşlem günlüğünde gör →';a.addEventListener('click',function(e){e.preventDefault();var r=document.getElementById('sync-log-'+(d.log.id||0));if(r){r.scrollIntoView({behavior:'smooth',block:'center'});r.classList.add('log-row-flash');setTimeout(function(){r.classList.remove('log-row-flash')},2200)}});res.appendChild(a);}if(d.series&&d.series.length){var maxP=0,maxA=0;d.series.forEach(function(s){if(s.price!==null&&s.price!==undefined&&s.price>maxP)maxP=s.price;if(s.allotment!==null&&s.allotment!==undefined&&s.allotment>maxA)maxA=s.allotment;});var wrap=document.createElement('div');wrap.className='room-series';var head=document.createElement('div');head.className='room-series-head';head.textContent='Son 30 gün: fiyat / kontenjan