='post';var fields={csrf:csrfEl?csrfEl.value:'',action:'plan_map_approve',mapping_id:String(mapId),connection_id:ch.dataset.conn||'',property_id:ch.dataset.prop||''};for(var k in fields){var i=document.createElement('input');i.type='hidden';i.name=k;i.value=fields[k];f.appendChild(i);}document.body.appendChild(f);f.submit();}function planListVerify(ch){var res=document.getElementById('plan-list-verify');if(!res)return;res.hidden=false;res.textContent='…';res.className='room-verify-result';fetch('/nexustraveltech/api/supplier-plan-test.php?connection_id='+encodeURIComponent(ch.dataset.conn)+'&property_id='+encodeURIComponent(ch.dataset.prop)+'&code='+encodeURIComponent(ch.dataset.code),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(d){res.innerHTML='';var msg=document.createElement('div');msg.className='room-test-msg';msg.textContent=d.message||(d.ok?'Hazır':'Hata');res.appendChild(msg);if(d.sampleText){var box=document.createElement('div');box.className='room-sample-box';var head=document.createElement('div');head.className='room-sample-head';head.textContent='Örnek webhook yükü (rates, dış plan kodlu)';var cp=document.createElement('button');cp.type='button';cp.className='room-sample-copy';cp.textContent='⧉ Kopyala';head.appendChild(cp);var pre=document.createElement('pre');pre.className='room-sample-pre';pre.textContent=d.sampleText;box.appendChild(head);box.appendChild(pre);res.appendChild(box)}res.className='room-verify-result'+(d.ready?' ok':' err')}).catch(function(){res.textContent='Test yapılamadı (ağ/oturum).';res.className='room-verify-result err'})}document.querySelectorAll('.plan-unmatched-chip').forEach(function(ch){ch.addEventListener('click',function(){if(parseInt(ch.dataset.map||'0',10)>0){planApproveSuggestion(ch)}else{planListVerify(ch)}})});document.querySelectorAll('.chip-action[data-act="verify"][data-kind="plan"]').forEach(function(b){b.addEventListener('click',function(){var wrap=b.parentNode;var ch=wrap?wrap.querySelector('.plan-unmatched-chip'):null;if(ch)planListVerify(ch)})});document.querySelectorAll('[data-code-sortbox]').forEach(function(box){var sel=box.querySelector('.code-sort');if(!sel)return;var apply=function(){var mode=sel.value;var wrap=box.querySelector('.room-unmatched-codes');if(!wrap)return;var chips=Array.prototype.slice.call(wrap.querySelectorAll('.code-chip-wrap'));chips.sort(function(a,b){var av=mode==='t'?parseInt(a.getAttribute('data-t')||'0',10):parseInt(a.getAttribute('data-c')||'0',10);var bv=mode==='t'?parseInt(b.getAttribute('data-t')||'0',10):parseInt(b.getAttribute('data-c')||'0',10);return bv-av;});chips.forEach(function(c){wrap.appendChild(c);});};sel.addEventListener('change',apply);});</script><?php supply_end(); ?>
